      { chord: ['C3', 'E3', 'G3'], bass: 'C2' }, { chord: ['A2', 'C3', 'E3'], bass: 'A1' },
      { chord: ['F2', 'A2', 'C3'], bass: 'F1' }, { chord: ['G2', 'B2', 'D3'], bass: 'G1' },
    ]
