          <button className={`accompaniment ${accompaniment ? 'on' : ''}`} onClick={() => void toggleAccompaniment()}><span><Sparkles size={14} /> Accompaniment</span><strong>{accompaniment ? 'On' : 'Off'}</strong></button>
        </aside>
      </section>

